"""Encode synthetic tones only; tests consume checked-in packets, not FFmpeg CLI."""
from pathlib import Path
import hashlib
import shutil
import subprocess

root = Path(__file__).resolve().parent
ffmpeg = shutil.which("ffmpeg")
if not ffmpeg:
    raise SystemExit("ffmpeg required to regenerate fixtures")
lines = ["// Synthetic 48 kHz tones, generated by generate.py.", "#pragma once",
         "#include <array>", "#include <cstdint>", "#include <span>", "namespace EsvmAc3Fixture {"]
for codec in ("ac3", "eac3"):
    for surround in (False, True):
        name = codec + ("Surround" if surround else "Stereo")
        # 5.1 fixture has ONLY center-channel 660 Hz: actual downmix must put
        # signal in both output channels, not merely retain front L/R silence.
        expr = "0|0|0.25*sin(2*PI*660*t)|0|0|0" if surround else "0.25*sin(2*PI*440*t)|0.25*sin(2*PI*880*t)"
        layout = "5.1" if surround else "stereo"
        data = subprocess.check_output([ffmpeg, "-hide_banner", "-loglevel", "error", "-f", "lavfi",
            "-i", f"aevalsrc={expr}:s=48000:c={layout}", "-frames:a", "3", "-map_metadata", "-1",
            "-c:a", codec, "-b:a", "192k", "-threads", "1", "-flags:a", "+bitexact", "-f", codec, "pipe:1"])
        # Both encoders produce 1536-sample, 768-byte frames at 192k/48k.
        assert len(data) >= 3 * 768 and len(data) % 768 == 0
        data = data[:3 * 768] # Encoder flushing may append a padded frame.
        for index in range(3):
            packet = data[index * 768:(index + 1) * 768]
            assert packet[:2] == b"\x0b\x77"
            lines.append(f"inline constexpr std::array<uint8_t, 768> {name}{index} {{")
            for start in range(0, len(packet), 16):
                lines.append("\t" + ", ".join(f"0x{b:02x}" for b in packet[start:start + 16]) + ",")
            lines.append("};")
        lines.append(f"inline constexpr std::array<std::span<const uint8_t>, 3> {name} {{{name}0, {name}1, {name}2}};")
        print(name, hashlib.sha256(data).hexdigest())
lines.extend(["} // namespace EsvmAc3Fixture", ""])
(root / "packets.h").write_text("\n".join(lines), encoding="utf-8")
print(subprocess.check_output([ffmpeg, "-version"], text=True).splitlines()[0])
